const p=document.getElementById('prompt'),r=document.getElementById('result'),steps=document.getElementById('steps'),intent=document.getElementById('intent'),explain=document.getElementById('explain');
document.querySelectorAll('.example').forEach(b=>b.onclick=()=>p.value=b.textContent);
function analyze(s){s=s.toLowerCase();let out=[],label='General task';if(/qr|qrcode|quick response/.test(s)){label='QR generation';out=[['📱','Create QR Code','Generate a QR code from the supplied URL or text.']]}else if(/json|format|beautif/.test(s)&&/json/.test(s)){label='JSON formatting';out=[['{ }','Format JSON','Validate and beautify the JSON input.']]}else{label='Image optimization';if(/resize|size|1200|pixel|px/.test(s))out.push(['📐','Resize Images','Apply the requested image dimensions.']);if(/compress|smaller|optimi[sz]/.test(s))out.push(['⚡','Compress Images','Reduce file size for web or sharing.']);if(/webp/.test(s))out.push(['🔄','Convert to WebP','Convert supported images to WebP format.']);if(!out.length)out=[['🖼️','Analyze Image Task','Select the best available image tool for the request.']];}return {label,out}}
document.getElementById('run').onclick=()=>{const v=p.value.trim();if(!v){p.focus();return}const a=analyze(v);intent.textContent=a.label;steps.innerHTML=a.out.map((x,i)=>`<div class="step"><span class="num">${i+1}</span><span style="font-size:19px">${x[0]}</span><div><b>${x[1]}</b><small>${x[2]}</small></div></div>`).join('');explain.textContent=`Detected from your request: “${v}”. The demo converts the intent into ${a.out.length} SmartToolz workflow step${a.out.length>1?'s':''}.`;r.classList.add('show');r.scrollIntoView({behavior:'smooth',block:'nearest'})};
